#!/usr/bin/env bash
# CI guard: fail when Plugin/awesome-ds/ds/ differs from AwesomeDS/,
# or Plugin/awesome-ds/knowledge/ differs from Knowledge/ (README.md excluded on both sides;
# the plugin index is generated by scripts/build-reference.mjs and checked there).
# Fix with: bash Plugin/awesome-ds/scripts/sync-ds.sh
set -uo pipefail

PLUGIN_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
REPO_ROOT="$PLUGIN_ROOT/../.."
status=0

# compare <src-dir> <dst-dir> <label> [extra diff args...]
compare() {
  local src="$1" dst="$2" label="$3"
  shift 3
  if [ ! -d "$src" ]; then
    echo "check-sync: source not found: $src" >&2
    exit 2
  fi
  if [ ! -d "$dst" ]; then
    echo "check-sync: $label copy missing. Run scripts/sync-ds.sh" >&2
    status=1
    return
  fi
  if diff -r --exclude '.DS_Store' "$@" "$src" "$dst" >/dev/null; then
    echo "check-sync: OK, Plugin/awesome-ds/$label matches"
  else
    echo "check-sync: OUT OF SYNC in Plugin/awesome-ds/$label. Differences:" >&2
    diff -rq --exclude '.DS_Store' "$@" "$src" "$dst" >&2 || true
    status=1
  fi
}

compare "$REPO_ROOT/AwesomeDS" "$PLUGIN_ROOT/ds" "ds/"
compare "$REPO_ROOT/Knowledge" "$PLUGIN_ROOT/knowledge" "knowledge/" --exclude README.md

if [ "$status" -ne 0 ]; then
  echo "Run: bash Plugin/awesome-ds/scripts/sync-ds.sh" >&2
fi
exit "$status"
